export const CrescentMoonIcon = () => {
  // a crescent moon with some craters on it, kind of like the one in the stats screen, but simplified and a sharp, slim crescent.
  return (
    <svg viewBox="0 0 100 100" className="w-full h-full" fill="currentColor">
      <defs>
        <clipPath id="crescent-clip">
          <path d="M 50 5 A 45 45 0 0 1 50 95 A 35 45 0 0 0 50 5 Z" />
        </clipPath>
      </defs>
      <g clipPath="url(#crescent-clip)">
        {/* Moon body */}
        <path
          d="M 50 5 A 45 45 0 0 1 50 95 A 35 45 0 0 0 50 5 Z"
          fill="currentColor"
        />
        {/* Craters */}
        <circle cx="55" cy="25" r="3" opacity="0.3" />
        <circle cx="58" cy="50" r="4" opacity="0.3" />
        <circle cx="56" cy="70" r="2.5" opacity="0.3" />
        <circle cx="62" cy="40" r="2" opacity="0.3" />
      </g>
    </svg>
  );
};

export const TwentyFourHoursIcon = () => {
  // a clock face with a 24 on it in the font orbitron, and maybe some small clock hands to make it clear it's a clock. The 24 should be the main focus though.
  return (
    <svg
      viewBox="0 0 100 100"
      className="w-full h-full"
      fill="none"
      stroke="currentColor"
    >
      <defs>
        <mask id="clock-mask">
          <rect width="100" height="100" fill="white" />
          {/* Cut out area for "24" */}
          <rect x="60" y="70" width="35" height="28" fill="black" />
        </mask>
      </defs>
      {/* Clock circle with mask */}
      <circle
        cx="50"
        cy="50"
        r="45"
        strokeWidth="5"
        fill="none"
        mask="url(#clock-mask)"
      />
      {/* Hour markers */}
      <line
        x1="50"
        y1="8"
        x2="50"
        y2="15"
        strokeWidth="4"
        strokeLinecap="round"
      />
      <line
        x1="50"
        y1="85"
        x2="50"
        y2="92"
        strokeWidth="4"
        strokeLinecap="round"
        mask="url(#clock-mask)"
      />
      <line
        x1="8"
        y1="50"
        x2="15"
        y2="50"
        strokeWidth="4"
        strokeLinecap="round"
      />
      <line
        x1="85"
        y1="50"
        x2="92"
        y2="50"
        strokeWidth="4"
        strokeLinecap="round"
      />
      {/* Clock hands showing 11:00 */}
      <line
        x1="50"
        y1="50"
        x2="46"
        y2="28"
        strokeWidth="5"
        strokeLinecap="round"
      />
      <line
        x1="50"
        y1="50"
        x2="21"
        y2="34"
        strokeWidth="5"
        strokeLinecap="round"
      />
      <circle cx="50" cy="50" r="3" fill="currentColor" />
      {/* 24 Text in bottom right */}
      <text
        x="77"
        y="97"
        fontFamily="Orbitron, monospace"
        fontSize="34"
        fontWeight="bold"
        textAnchor="middle"
        fill="currentColor"
      >
        24
      </text>
    </svg>
  );
};

